  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Desvenlafaxine, which shares the p-hydroxyphenyl motif, has an absolute oral bioavailability of about 80% in patients, showing that this phenolic substructure is compatible with high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Zeaxanthin, a highly lipophilic polyene with hydroxyl groups, is reported to have high oral bioavailability when ingested with fat, supporting that the query's long polyene/lipophilic structure can be well absorbed under food or formulation conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Teriflunomide, an aromatic amide, has absolute oral bioavailability approaching 100%, indicating that the amide linkage in the query is not a barrier to high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Meperidine, despite substantial first-pass metabolism, has oral bioavailability around 45-60%, still well above the 20% threshold; the query's more stable amide is not expected to be lower on this basis.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Estetrol, a phenolic steroid, has high oral bioavailability in humans, providing additional support that phenolic lipophilic molecules can exceed the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All retrieved transferable experimental evidence supports oral bioavailability at or above 20%, with many analogues showing 45-100% F and no affirmative evidence of low F; therefore predict high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself.",
    "Some supporting records are not explicitly absolute bioavailability and may reflect relative or food-dependent absorption.",
    "The query's very low aqueous solubility is a potential absorption limitation not directly tested in the retrieved evidence."
  ],
